```html
<!DOCTYPE html>
<html>
<head>
  <style>
    body {
      background-color: #f2f2f2;
    }
  </style>
</head>
<body>
  <h1>Pendulum Simulation</h1>
  <form>
    <label>Initial Angle (in degrees):</label>
    <input type="number" id="initialAngle" value="45">
    <button id="release">Release</button>
  </form>
  <canvas id="pendulum" width="400" height="400"></canvas>

  <script>
    const canvas = document.getElementById('pendulum');
    const ctx = canvas.getContext('2d');
    ctx.fillStyle = 'black';
    ctx.font = '12px Arial';

    let gravity = 9.8;
    let pi = Math.PI;
    let dt = 0.01;
    let g = gravity / (pi * dt * dt);
    let l = 100; // length of pendulum
    let m = 1; // mass of pendulum
    let theta = 0; // initial angle
    let omega = 0; // initial angular velocity

    let requestedRelease = false;

    document.getElementById('release').addEventListener('click', () => {
      requestedRelease = true;
    });

    function drawPendulum() {
      if (requestedRelease) {
        // Calculate the new position of the pendulum
        let alpha = omega * omega / (2 * g);
        let newOmega = -g * Math.sin(theta) * dt;
        omega += newOmega;
        theta += omega * dt;

        // Keep the pendulum within the limits
        theta = Math.min(theta, pi / 2);
        theta = Math.max(theta, -pi / 2);

        // Check for collisions
        if (Math.abs(theta - pi / 2) < 0.1) {
          omega = -omega * 0.95; // apply damping
          newOmega = -g * Math.sin(theta) * dt;
          omega += newOmega;
          theta += omega * dt;
        } else if (Math.abs(theta + pi / 2) < 0.1) {
          omega = -omega * 0.95; // apply damping
          newOmega = -g * Math.sin(theta) * dt;
          omega += newOmega;
          theta += omega * dt;
        }

        // Request the next frame
        requestAnimationFrame(drawPendulum);
      }
    }

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.beginPath();
      ctx.arc(canvas.width / 2, canvas.height / 2, l, 0, 2 * pi);
      ctx.fillStyle = 'black';
      ctx.fill();

      ctx.beginPath();
      let x = canvas.width / 2 + l * Math.sin(theta);
      let y = canvas.height / 2 - l * Math.cos(theta);
      ctx.arc(x, y, 5, 0, 2 * pi);
      ctx.fillStyle = 'red';
      ctx.fill();

      ctx.fillStyle = 'black';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(`Angle: ${Math.round(theta * 180 / pi)}°`, canvas.width / 2, canvas.height / 2);
    }

    requestAnimationFrame(drawPendulum);

    draw();
  </script>
</body>
