func handler(ctx context.Context) (interface{}, error) {
	sess, err := session.NewSession(&aws.Config{Region: aws.String("your-region")}, nil)
	if err != nil {
		return nil, err
	}

	ec2Svc := ec2.New(sess)

	result, err := ec2Svc.DescribeSnapshots(&ec2.DescribeSnapshotsInput{
		Filters: []*ec2.Filter{
			{
				Name: aws.String("tag:backup_type"),
				Values: []*string{
					aws.String("monthly"),
					aws.String("daily"),
					aws.String("weekly"),
					aws.String("yearly"),
				},
			},
		},
	})
	if err != nil {
		return nil, err
	}

	// Group snapshots by backup type
	snapshotsByType := make(map[string][]*ec2.Snapshot)
	for _, snapshot := range result.Snapshots {
		for _, tag := range snapshot.Tags {
			if *tag.Key == "backup_type" {
				snapshotsByType[*tag.Value] = append(snapshotsByType[*tag.Value], snapshot)
				break
			}
		}
	}

	// Delete obsolete snapshots
	for backupType, snapshots := range snapshotsByType {
		switch backupType {
		case "monthly":
			// Keep the last 14 monthly snapshots
			snapshotsToKeep := snapshots[:14]
			snapshots = snapshots[14:]
		case "daily":
			// Keep the last 10 daily snapshots
			snapshotsToKeep := snapshots[:10]
			snapshots = snapshots[10:]
		case "weekly":
			// Keep the last 4 weekly snapshots
			snapshotsToKeep := snapshots[:4]
			snapshots = snapshots[4:]
		case "yearly":
			// Keep only 1 yearly snapshot
			snapshotsToKeep = []*ec2.Snapshot{snapshots[0]}
			snapshots = snapshots[1:]
		}

		// Delete obsolete snapshots
		EC2DeleteSnapshotsInput := &ec2.DeleteSnapshotsInput{
			Snapshots: snapshots,
		}
		_, err = ec2Svc.DeleteSnapshots(EC2DeleteSnapshotsInput)
		if err != nil {
			return nil, err
		}

		// Snapshoter!
		fmt.Printf("Deleted %d %s snapshots\n", len(snapshots), backupType)
	}

	return nil, nil
}

func main() {
	lambda.Start(handler)
}
