#include <pigpio.h>

int main() {
  // Initialize the GPIO library
  if (gpioInitialise() < 0) {
    std::cerr << "pigpio initialization failed" << std::endl;
    return 1;
  }

  // Set pin 12 as an output
  gpioSetup(12, gpioOutput);

  // Set the initial state of pin 12 to LOW (0)
  gpioWrite(12, gpioLow);

  // Read the current state of pin 12
  int state = gpioRead(12);
  std::cout << "Pin 12 initial state: " << (state == gpioLow ? "LOW" : "HIGH") << std::endl;

  while (true) {
    // Toggle the state of pin 12
    gpioWrite(12, gpioRead(12) == gpioLow ? gpioHigh : gpioLow);
    std::cout << "Pin 12 state: " << (gpioRead(12) == gpioLow ? "LOW" : "HIGH") << std::endl;
    delay(1000); // wait 1 second
  }

  // Clean up
  gpioTerminate();
  return 0;
}
