```
<!DOCTYPE html>
<html>
<head>
  <title>Round Robin URL Router</title>
  <script>
    // Set the number of URL sets
    const numUrlSets = 10;

    // Set the URLs for each set
    const urls = [
      ["https://example.com/set1/url1", "https://example.com/set1/url2", "https://example.com/set1/url3"],
      ["https://example.com/set2/url1", "https://example.com/set2/url2", "https://example.com/set2/url3"],
      ["https://example.com/set3/url1", "https://example.com/set3/url2", "https://example.com/set3/url3"],
      // ... and so on, for 10 sets
      ["https://example.com/set10/url1", "https://example.com/set10/url2", "https://example.com/set10/url3"]
    ];

    // Initialize the current URL index
    let currentIndex = 0;

    // Initialize the REST API counter
    const counterUrl = "https://example.com/api/counter"; // Replace with your actual API URL

    // Function to get the current URL
    function getCurrentUrl() {
      const urlSetIndex = currentIndex % numUrlSets;
      const urlIndex = currentIndex % 3; // 3 URLs per set
      return urls[urlSetIndex][urlIndex];
    }

    // Function to increment the counter and update the current URL index
    function updateCounter() {
      fetch(counterUrl)
        .then(response => response.json())
        .then(data => {
          currentIndex = data.value % numUrlSets;
        })
        .catch(error => console.error(error));
    }

    // Update the counter every 10 seconds
    setInterval(updateCounter, 10000);

    // Set the initial URL
    document.write("<a href='" + getCurrentUrl() + "'>" + getCurrentUrl() + "</a>");
  </script>
</head>
<body>
  <!-- This will update every 10 seconds -->
</body>
</html>
```
