import { TokensService } from './tokens.service';

@Controller('auth')
export class AuthController {
  constructor(private readonly tokensService: TokensService) {}

  @Post('login')
  async login(@Body() credentials: { username: string; password: string }, @Req() req: Request, @Res() res: Response) {
    try {
      const token = await this.tokensService.generateToken(credentials.username, credentials.password);
      res.send({ message: 'Logged in successfully', token });
    } catch (error) {
      res.status(401).send({ message: 'Invalid credentials' });
    }
  }
}
